<template>
  <!-- The right bar is as wide as its content, so every row has one fixed
       width (name block, button) and an empty tab is held to it: switching
       networks must not resize the column and shift the feed. -->
  <div class="w-full lg:min-w-[23rem] rounded-lg bg-lightest my-4" data-tour="who-to-follow">
    <div class="p-3 flex items-center">
      <p class="text-lg font-bold">Who to follow</p>
    </div>
    <!-- One block, one icon tab per network: Warpnet first because it is the
         network the user is actually on. Labels show on hover only, so the row
         fits however many networks are bridged. -->
    <div class="flex gap-1 px-2 py-2 border-t border-lighter" role="tablist">
      <button
        v-for="tab in tabs"
        :key="tab.key"
        type="button"
        role="tab"
        :aria-selected="tab.key === activeTab"
        :aria-label="tab.label"
        @click="activeTab = tab.key"
        :class="['group relative flex-1 min-w-0 flex items-center justify-center px-2 py-1.5 rounded-full text-xs transition-colors flat-btn',
                 tab.key === activeTab
                   ? 'bg-lighter text-blue font-bold ring-1 ring-[color:var(--gd-trim)]'
                   : 'text-dark hover:bg-lighter']"
      >
        <NetworkIcon :network="tab.network" size-class="w-4 h-4 shrink-0" />
        <span class="pointer-events-none absolute top-full mt-1 z-10 whitespace-nowrap rounded bg-lighter px-2 py-0.5 text-xs text-dark ring-1 ring-[color:var(--gd-trim)] opacity-0 group-hover:opacity-100 transition-opacity">{{ tab.label }}</span>
      </button>
    </div>
    <div v-for="profile in activeProfiles" :key="profile.id" class="w-full flex hover:bg-lighter transition-colors duration-150 p-3 border-t border-lighter">
      <div class="grid flex-none">
        <img
          @click="pushToProfilePage(profile.id)"
          :src="profile.avatar || '/default_profile.png'"
          class="col-start-1 row-start-1 block w-12 h-12 rounded-full cursor-pointer object-cover bg-transparent"
          :alt="profile.username"
        />
        <UserStatusDot :user="profile" />
      </div>
      <div class="hidden lg:block ml-4 w-[9rem] flex-none">
        <p @click="pushToProfilePage(profile.id)" class="text-left text-sm font-bold leading-tight cursor-pointer truncate max-w-[9rem]">{{ profile.username }}</p>
        <p class="text-left text-sm leading-tight text-dark truncate max-w-[9rem]" :title="profile.id">{{ shortHandle(profile.id, 8) }}</p>
      </div>
      <button
        v-if="!isFollowing(profile.id)"
        @click="follow(profile.id)"
        :disabled="isPending(profile.id)"
        class="ml-auto w-[6.5rem] flex-none text-sm text-blue font-bold py-1 rounded-full border border-blue m-2 disabled:opacity-50"
      >
        Follow
      </button>
      <button
          v-if="isFollowing(profile.id)"
          @click="unfollow(profile.id)"
          :disabled="isPending(profile.id)"
          class="ml-auto w-[6.5rem] flex-none text-sm font-bold py-1 rounded-full border border-blue bg-blue text-white hover:bg-red-600 hover:border-red-600 m-2 disabled:opacity-50 group"
      >
        <span class="group-hover:hidden">Following</span>
        <span class="hidden group-hover:inline">Unfollow</span>
      </button>
    </div>
    <p v-if="activeProfiles.length === 0" class="p-3 border-t border-lighter text-sm text-dark text-left">
      Nobody to suggest here yet.
    </p>
    <button
        @click="showMore()"
        class="p-3 w-full hover:bg-lighter text-left text-blue border-t border-lighter"
    >
      Show More
    </button>
  </div>
</template>

<script>
import {warpnetService} from "@/service/service";
import {toast} from "@/lib/toast";
import {networkSections, sectionKey, shortHandle} from "@/lib/network";
import NetworkIcon from "@/components/NetworkIcon.vue";
import UserStatusDot from "@/components/UserStatusDot.vue";

const sectionLimit = 5;

export default {
  name: 'WhoToFollow',
  components: {NetworkIcon, UserStatusDot},
  props: ["profile"],
  data() {
    return {
      activeTab: 'warpnet',
      groups: {warpnet: [], mastodon: [], threads: []},
      followingStatus: new Map(),
      pending: new Set(),
    };
  },
  computed: {
    // Every tab is always offered, empty or not: a tab that appears only once
    // it has content hides the fact that the other networks exist at all.
    tabs() {
      return networkSections(Object.values(this.groups).flat());
    },
    activeProfiles() {
      return this.groupOf(this.activeTab);
    },
  },
  methods: {
    shortHandle,
    async pushToProfilePage(profileId) {
      this.$router.push({
        name: "Profile",
        params: {
          id: profileId
        }
      });
    },
    // groupOf / groupFor keep one bucket per network: the tab key on one
    // side, the network tag a profile carries on the other.
    groupOf(key) {
      if (!this.groups[key]) this.groups[key] = [];
      return this.groups[key];
    },
    groupFor(profile) {
      return this.groupOf(sectionKey(profile));
    },
    isFollowing(profileId) {
      return this.followingStatus.get(profileId) || false
    },
    isPending(profileId) {
      return this.pending.has(profileId);
    },
    async follow(profileId) {
      if (this.pending.has(profileId)) return;
      this.pending.add(profileId);
      this.followingStatus.set(profileId, true); // optimistic
      try {
        await warpnetService.followUser(profileId);
      } catch (err) {
        console.error('Failed to follow:', err);
        this.followingStatus.set(profileId, false); // rollback
        toast.error(err?.message || "Couldn't follow this user. Please try again.");
      } finally {
        this.pending.delete(profileId);
      }
    },
    async unfollow(profileId) {
      if (this.pending.has(profileId)) return;
      this.pending.add(profileId);
      this.followingStatus.set(profileId, false); // optimistic
      try {
        await warpnetService.unfollowUser(profileId);
      } catch (err) {
        console.error('Failed to unfollow:', err);
        this.followingStatus.set(profileId, true); // rollback
        toast.error(err?.message || "Couldn't unfollow this user. Please try again.");
      } finally {
        this.pending.delete(profileId);
      }
    },
    // Avatars fill in per row; a hanging or failed blob only leaves its own
    // default in place instead of holding (or crashing) the whole block.
    loadAvatars(profiles) {
      for (const p of profiles) {
        warpnetService.getImage({userId: p.id, key: p.avatar_key})
            .then((avatar) => {
              if (!avatar) return;
              const group = this.groupFor(p);
              const i = group.findIndex((x) => x && x.id === p.id);
              if (i !== -1) group.splice(i, 1, {...group[i], avatar});
            })
            .catch((err) => console.warn(`failed to load avatar for [${p.id}]:`, err));
      }
    },
    showMore() {
      this.$router.push({ name: "WhoToFollow" });
    },
   },
  async created() {
    console.log("loading component:", this.$options.name);
    // Every network comes with its own page and cursor; a network whose tab
    // is still short after filtering gets its next page (bounded).
    let cursors = {};
    try {
      for (let round = 0; round < 5; round++) {
        const entries = Object.entries(await warpnetService.getWhoToFollow(cursors, sectionLimit * 2));
        // Friends of friends first; the order within each part is the node's.
        const sorted = await Promise.all(entries.map(([, page]) => warpnetService.circleFirst(page.users)));
        cursors = {};
        for (const [i, [network, page]] of entries.entries()) {
          for (const p of sorted[i]) {
            const group = this.groupFor(p);
            if (group.length < sectionLimit && !group.some((x) => x.id === p.id)) {
              group.push(p);
            }
          }
          if (network && page.cursor && this.groupOf(network).length < sectionLimit) {
            cursors[network] = page.cursor;
          }
        }
        if (Object.keys(cursors).length === 0) {
          break;
        }
      }
    } catch (err) {
      console.error("loading component:", this.$options.name, err);
    }
    const profiles = Object.values(this.groups).flat();
    this.loadAvatars(profiles);
    for (const p of profiles) {
      try {
        this.followingStatus.set(p.id, await warpnetService.isFollowing(p.id));
      } catch (err) {
        console.warn(`failed to load follow state for [${p.id}]:`, err);
      }
    }
  },
};
</script>